  mask-image: linear-gradient(90deg, transparent, #000 5%, #000 95%, transparent); }
.carosello-track { display: flex; gap: 22px; width: max-content; animation: scorriCorsi 42s linear infinite; }
.corsi-carosello:hover .carosello-track { animation-play-state: paused; }
@keyframes scorriCorsi { from { transform: translateX(0); } to { transform: translateX(-50%); } }
.cover-card { position: relative; flex: 0 0 auto; width: clamp(230px, 26vw, 288px); height: clamp(310px, 34vw, 384px);
  border-radius: 20px; overflow: hidden; box-shadow: var(--ombra); text-decoration: none; transition: var(--transizione); }
