.vision-big { font-family: var(--font-titolo); font-weight: 600; font-size: clamp(6rem, 20vw, 15rem); line-height: .85;
  color: transparent; -webkit-text-stroke: 2px rgba(127,182,255,.55); background: none; letter-spacing: .01em; }
.vision-big .anni { display: block; -webkit-text-stroke: 0; color: var(--oro-chiaro); font-size: clamp(1.4rem, 4vw, 2.4rem); letter-spacing: .38em; margin-top: 6px; text-transform: uppercase; }
