/* =========================================================
   CARD A FOTO PIENA (testo sovrapposto) + CAROSELLO frecce/drag
   ========================================================= */
.photo-card { position: relative; display: block; height: 420px; border-radius: 18px; overflow: hidden; box-shadow: var(--ombra); background: var(--verde-scuro); }
.photo-card img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: transform .6s ease; }
.photo-card::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(6,14,32,.10) 30%, rgba(6,14,32,.55) 62%, rgba(6,14,32,.94) 100%); }
.photo-card:hover img { transform: scale(1.05); }
.photo-card .pc-tag { position: absolute; top: 14px; left: 14px; z-index: 3; background: rgba(46,144,255,.92); color: #fff; font-size: .64rem; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; padding: 5px 12px; border-radius: 50px; }
.photo-card .pc-body { position: absolute; left: 0; right: 0; bottom: 0; z-index: 3; padding: 22px 20px; color: #fff; }
.photo-card .pc-body h3 { color: #fff; font-size: 1.4rem; line-height: 1.12; margin-bottom: 10px; text-shadow: 0 2px 10px rgba(0,0,0,.5); }
