.photo-card .pc-price small { font-size: .7rem; color: rgba(235,243,254,.75); font-family: var(--font-testo); }
.photo-card .pc-btn { background: var(--oro); color: var(--verde-scuro); border-radius: 50px; padding: 10px 20px; font-weight: 600; font-size: .85rem; white-space: nowrap; transition: var(--transizione); }
.photo-card .pc-btn:hover { background: #fff; }

/* carosello con frecce + drag */
.car-wrap { position: relative; }
.car-viewport { overflow: hidden; }
.car-track { display: flex; will-change: transform; user-select: none; cursor: grab; }
.car-track.dragging { cursor: grabbing; }
.car-track .photo-card { flex: 0 0 auto; width: 300px; margin-right: 22px; }
.car-track a, .car-track img { -webkit-user-drag: none; user-drag: none; }
.car-arrow { position: absolute; top: 50%; transform: translateY(-50%); z-index: 6; width: 48px; height: 48px; border-radius: 50%; border: none; background: var(--verde-scuro); color: #fff; font-size: 1.5rem; line-height: 1; cursor: pointer; display: grid; place-items: center; box-shadow: var(--ombra); transition: var(--transizione); opacity: .92; }
.car-arrow:hover { background: var(--oro); color: var(--verde-scuro); opacity: 1; }
